_NBSP = "\u00a0"

# Link names Meridale rejects, with the canonical id to send (meridale-time-zones).
_LINKS = {
    "US/Pacific": "America/Los_Angeles",
    "US/Eastern": "America/New_York",
    "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata",
    "Asia/Saigon": "Asia/Ho_Chi_Minh",
    "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires",
    "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC",
    "GMT": "Etc/UTC",
}

_FIXED_OFFSET = re.compile(r"^(?:UTC|GMT)?\s*([+-])(\d{1,2})(?::?(\d{2}))?$", re.IGNORECASE)


def _system_links() -> dict[str, str]:
    """Link name -> target from the installed tz database, when it is available."""
    for directory in ("/usr/share/zoneinfo", "/usr/lib/zoneinfo", "/usr/share/lib/zoneinfo", "/etc/zoneinfo"):
        try:
            with open(os.path.join(directory, "tzdata.zi"), encoding="utf-8") as f:
                found = {}
                for row in f:
                    parts = row.split()
                    if len(parts) == 3 and parts[0] == "L":
                        found[parts[2]] = parts[1]
                return found
        except OSError:
            continue
    return {}


def _zone(tz: str) -> str:
    """The canonical zone id Meridale accepts for the zone or fixed offset stored for a merchant."""
    tz = tz.strip()
    m = _FIXED_OFFSET.match(tz)
    if m:
        sign, hours, minutes = m.group(1), int(m.group(2)), int(m.group(3) or 0)
        if minutes:
            raise ValueError(f"unsupported fixed offset {tz!r}: only whole hours exist")
        if hours == 0:
            return "Etc/UTC"
        # POSIX convention: the sign of the Etc zone names is inverted.
        return f"Etc/GMT{'-' if sign == '+' else '+'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    links = _system_links()
    seen = set()
    while tz in links and tz not in seen:
        seen.add(tz)
        tz = links[tz]
    return _LINKS.get(tz, tz)


_SUPPORTED_LOCALES = ("en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP")


def _locale(posix: str) -> str:
    """The supported BCP 47 locale for the POSIX locale of an account (meridale-locales)."""
    name = re.split(r"[.@]", posix.strip(), maxsplit=1)[0]
    parts = [p for p in re.split(r"[-_]", name) if p]
    if not parts:
        return "en-US"
    language = parts[0].lower()
    region = parts[1].upper() if len(parts) > 1 and len(parts[1]) in (2, 3) else None
    if region and f"{language}-{region}" in _SUPPORTED_LOCALES:
        return f"{language}-{region}"
    if language in _SUPPORTED_LOCALES:
        return language
    return "en-US"


def _digits(currency: str) -> int:
    currency = currency.upper()
    if currency in ("CLP", "ISK", "JPY", "KRW", "UGX", "VND"):
        return 0
    if currency in ("BHD", "JOD", "KWD", "OMR", "TND"):
        return 3
    return 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value.strip()).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _group(integer: str, locale: str) -> str:
    if locale == "es" and len(integer) <= 4:
        return integer
    if locale == "en-IN":
        if len(integer) <= 3:
            return integer
        head, tail = integer[:-3], integer[-3:]
        pieces = []
        while len(head) > 2:
            pieces.insert(0, head[-2:])
            head = head[:-2]
        if head:
            pieces.insert(0, head)
        return ",".join(pieces + [tail])
    pieces = []
    while len(integer) > 3:
        pieces.insert(0, integer[-3:])
        integer = integer[:-3]
    pieces.insert(0, integer)
    return _SEPARATORS.get(locale, (".", ","))[1].join(pieces)


# locale -> (decimal separator, group separator)
_SEPARATORS = {
    "pt-BR": (",", "."),
    "de-DE": (",", "."),
    "es": (",", "."),
    "de-CH": (".", "\u2019"),
    "fr-FR": (",", "\u202f"),
}


def _text(value: Decimal, currency: str, locale: str, digits: int) -> str:
    """An amount as the Meridale dashboard writes it (meridale-display)."""
    decimal_sep, group_sep = _SEPARATORS.get(locale, (".", ","))
    negative = value < 0
    plain = f"{abs(value):.{digits}f}"
    integer, _, fraction = plain.partition(".")
    if locale == "es" and len(integer) <= 4:
        grouped = integer
    elif locale == "en-IN":
        grouped = _group(integer, locale)
    else:
        grouped = group_sep.join(_chunks(integer))
    number = ("-" if negative else "") + grouped + (decimal_sep + fraction if digits else "")
    if locale in ("de-DE", "es", "de-CH", "fr-FR"):
        return f"{number}{_NBSP}{currency}"
    return f"{currency}{_NBSP}{number}"


def _chunks(integer: str) -> list[str]:
    pieces = []
    while len(integer) > 3:
        pieces.insert(0, integer[-3:])
        integer = integer[:-3]
    pieces.insert(0, integer)
    return pieces

